L=len(seq)
comp=str.maketrans('ACGT','TGCA')
def rc(s): return s.translate(comp)[::-1]
rcseq=rc(seq)

def find_repeats(seq,k,minocc=2):
    seen={}
    for i in range(len(seq)-k+1):
        seen.setdefault(seq[i:i+k],[]).append(i)
    hits=[]
    seenrc={}
    for i in range(len(rcseq)-k+1):
        seenrc.setdefault(rcseq[i:i+k],[]).append(i)
    for km,pos in seen.items():
        if len(pos)>=minocc:
            # merge overlapping
            grp=[pos[0]]
            out=[]
            for p in pos[1:]:
                if p-grp[-1]<k: grp.append(p)
                else: out.append(grp); grp=[p]
            out.append(grp)
            for g in out:
                if len(g)>=minocc:
                    hits.append((g[-1]-g[0]+k, 'FWD', g[0]+1, g[-1]+1, km, len(g)))
    for km,pos in seenrc.items():
        if len(pos)>=minocc:
            grp=[pos[0]]; out=[]
            for p in pos[1:]:
                if p-grp[-1]<k: grp.append(p)
                else: out.append(grp); grp=[p]
            out.append(grp)
            for g in out:
                if len(g)>=minocc:
                    # convert rc coords to forward
                    f=[L-(p+k-1) for p in g]
                    hits.append((g[-1]-g[0]+k, 'REV', min(f), max(f)+1, km, len(g)))
    hits.sort(key=lambda x:-x[0])
    return hits

